import {BrowserProvider,Contract,ContractFactory,formatEther,parseEther} from '../assets/ethers.min.js';
import {getWalletSession} from '../wallet-session.mjs?v=35';
import {TESTNET,TESTNET_ITEMS} from '../testnet-items.mjs?v=35';
const $=id=>document.getElementById(id),session=getWalletSession();let config=null,artifacts=null,busy=false,selected=null,mask=0n,balance=0n,identity='';
const status=(text,error=false)=>{$('testStatus').textContent=text;$('testStatus').classList.toggle('error',error);};
const storage={read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}};
const deployments=()=>storage.read('getaway-testnet-deploy-v1',{}),claims=()=>storage.read('getaway-testnet-claims-v1',{});
async function api(path,body){const response=await fetch('/api/testnet/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(40000)});const data=await response.json();if(!response.ok)throw Error(data.error||'The workshop could not save. Try again.');return data;}
function wallet(){const p=session.getProvider();if(!p)throw Error('Connect a browser wallet at the top of this page first.');return p;}
async function signer(){const p=wallet();if(BigInt(await p.request({method:'eth_chainId'}))!==BigInt(TESTNET.chainId))throw Error('Switch to Robinhood Chain Testnet first.');const provider=new BrowserProvider(p);return {provider,signer:await provider.getSigner()};}
async function assertWallet(s){const p=wallet(),chain=await p.request({method:'eth_chainId'}),accounts=await p.request({method:'eth_accounts'});if(BigInt(chain)!==BigInt(TESTNET.chainId)||accounts[0]?.toLowerCase()!==(await s.getAddress()).toLowerCase())throw Error('Your wallet or network changed. Review this action again.');}
async function load(){config=await api('config');artifacts=await(await fetch('/testnet/artifacts.json')).json();render();await refresh();}
function render(){const enabled=config?.enabled;const box=$('testContracts');box.replaceChildren();if(enabled){for(const [label,address]of [['TOKEN',config.token],['SHOP',config.registry]]){const link=document.createElement('a');link.href=TESTNET.explorer+'/address/'+address;link.target='_blank';link.rel='noopener noreferrer';link.textContent=label+' · '+address;box.append(link,document.createElement('br'));}}else box.textContent='No test contracts connected to this account yet.';
 $('registry').value=config?.registry||new URL(location.href).searchParams.get('registry')||'';
 $('testItems').innerHTML=TESTNET_ITEMS.map(item=>{const owned=!!(mask&(1n<<BigInt(item.itemId))),pending=claims()[config?.registry+':'+session.state().account?.toLowerCase()+':'+item.itemId];return '<article class="life-card"><small>'+item.kind.toUpperCase()+' / '+(owned?'OWNED':item.cost.toLocaleString()+' tGETAWAY')+'</small><h3>'+item.name+'</h3><p>'+item.description+'</p><button data-item="'+item.itemId+'" '+(!enabled||busy||owned?'disabled':'')+'>'+(owned?'OWNED ON TESTNET':'REVIEW · '+item.cost.toLocaleString())+'</button>'+(pending?'<button class="pending" data-claim="'+item.itemId+'">VERIFY GAME UNLOCK</button><a href="'+TESTNET.explorer+'/tx/'+pending+'" target="_blank" rel="noopener noreferrer">VIEW BURN ↗</a>':'')+'</article>';}).join('');
 document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{selected=TESTNET_ITEMS.find(i=>i.itemId===Number(b.dataset.item));$('reviewItem').textContent=selected.name;$('reviewCost').textContent='EXACT COST: '+selected.cost.toLocaleString()+' tGETAWAY · Robinhood Chain Testnet';$('testReview').showModal();});
 document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>run(()=>claim(Number(b.dataset.claim))));
 $('testMint').disabled=!enabled||busy;$('testLink').disabled=!enabled||busy;$('testDeploy').disabled=busy||enabled;$('testShare').disabled=!enabled;$('testNetwork').disabled=busy;
}
async function refresh(){const s=session.state();$('testAccount').textContent=s.account||'Wallet not connected';if(!s.account){$('testGas').textContent='Connect your wallet to check test ETH.';$('testBalance').textContent='Connect your wallet to view test tokens.';render();return;}if(BigInt(s.chainId||'0')!==BigInt(TESTNET.chainId)){$('testGas').textContent='Switch to testnet to check your gas.';$('testBalance').textContent='Testnet wallet required.';render();return;}const {provider}=await signer();$('testGas').textContent=Number(formatEther(await provider.getBalance(s.account))).toFixed(6)+' test ETH';if(config?.enabled){const token=new Contract(config.token,artifacts.GetawayTestToken.abi,provider),shop=new Contract(config.registry,artifacts.GetawayNeighborhoodUnlocks.abi,provider);[mask,balance]=await Promise.all([shop.ownedMask(s.account),token.balanceOf(s.account)]);$('testBalance').textContent=Number(formatEther(balance)).toLocaleString()+' tGETAWAY · '+(config.wallet?.toLowerCase()===s.account.toLowerCase()?'Wallet linked':'Link wallet to save game rewards');render();}}
async function run(fn){if(busy)return;busy=true;render();try{await fn();}catch(e){status(e.code===4001||e.code==='ACTION_REJECTED'?'Cancelled in your wallet. You can continue when ready.':e.shortMessage||e.message,true);}finally{busy=false;render();}}
async function receipt(provider,hash){const r=await provider.waitForTransaction(hash,2,120000);if(!r)throw Error('This transaction is still pending. Keep its hash and check again.');if(r.status!==1)throw Error('The transaction failed. No unlock was granted.');return r;}
async function deploy(){const {provider,signer:s}=await signer(),address=await s.getAddress(),saved=deployments(),d=saved[address.toLowerCase()]||{};const remember=()=>{saved[address.toLowerCase()]=d;storage.write('getaway-testnet-deploy-v1',saved);};
 async function one(name,key,args){await assertWallet(s);if(d[key+'Hash']&&!d[key]){const prior=await provider.getTransactionReceipt(d[key+'Hash']);if(prior&&prior.status===0){delete d[key+'Hash'];remember();}}if(d[key])return d[key];if(d[key+'Hash']){status('Checking your pending '+name+' deployment…');const r=await receipt(provider,d[key+'Hash']);if(!r.contractAddress)throw Error('The deployment receipt did not contain a contract address.');d[key]=r.contractAddress;remember();return d[key];}status('Confirm '+name+' deployment in your wallet. Test ETH pays the network fee.');const a=artifacts[name],contract=await new ContractFactory(a.abi,a.bytecode,s).deploy(...args);d[key+'Hash']=contract.deploymentTransaction().hash;remember();const r=await receipt(provider,d[key+'Hash']);d[key]=r.contractAddress;remember();return d[key];}
 const token=await one('GetawayTestToken','token',[]),registry=await one('GetawayNeighborhoodUnlocks','registry',[token]);status('Verifying the deployed test contracts…');config=await api('setup',{registry});status('Your test shop is ready. Link your wallet and claim free test tokens.');await refresh();}
async function link(){const {signer:s}=await signer(),address=await s.getAddress();const challenge=await api('challenge',{wallet:address});status('Sign the wallet-link message. It does not approve tokens or charge a payment.');await assertWallet(s);const signature=await s.signMessage(challenge.message);const result=await api('link',{signature});config.wallet=result.wallet;status('Wallet linked to this game account.');await refresh();}
async function claim(itemId,hash){const key=config.registry+':'+session.state().account?.toLowerCase()+':'+itemId,h=hash||claims()[key];if(!h)throw Error('Paste the burn transaction hash below to verify it.');status('Checking the burn receipt and ownership on Robinhood Chain Testnet…');const result=await api('claim',{itemId,hash:h});const pending=claims();delete pending[key];storage.write('getaway-testnet-claims-v1',pending);status(result.item+' verified. Return to the game to equip it.');}
async function burn(){if(!selected)return;const item=selected;selected=null;const {provider,signer:s}=await signer(),address=await s.getAddress();if(config.wallet?.toLowerCase()!==address.toLowerCase())throw Error('Link this wallet to your player before burning.');const token=new Contract(config.token,artifacts.GetawayTestToken.abi,s),shop=new Contract(config.registry,artifacts.GetawayNeighborhoodUnlocks.abi,s),cost=parseEther(String(item.cost)),price=await shop.prices(item.itemId);if(price!==cost)throw Error('The onchain price changed. This burn was stopped.');if(await token.balanceOf(address)<cost)throw Error('Claim free test tokens before this burn.');const allowance=await token.allowance(address,config.registry);if(allowance<cost){if(allowance>0n){status('Reset the old token allowance in your wallet.');await assertWallet(s);await receipt(provider,(await token.approve(config.registry,0)).hash);}status('Approve exactly '+item.cost+' tGETAWAY in your wallet.');await assertWallet(s);await receipt(provider,(await token.approve(config.registry,cost)).hash);}status('Confirm the '+item.name+' test burn in your wallet.');await assertWallet(s);const tx=await shop.unlock(item.itemId,cost),key=config.registry+':'+address.toLowerCase()+':'+item.itemId,pending=claims();pending[key]=tx.hash;storage.write('getaway-testnet-claims-v1',pending);status('Burn submitted. Waiting for two testnet blocks…');await receipt(provider,tx.hash);await claim(item.itemId,tx.hash);await refresh();}
 $('testNetwork').onclick=()=>run(async()=>{const p=wallet();try{await p.request({method:'wallet_switchEthereumChain',params:[{chainId:TESTNET.hexChainId}]});}catch(e){if(e.code!==4902)throw e;await p.request({method:'wallet_addEthereumChain',params:[{chainId:TESTNET.hexChainId,chainName:TESTNET.name,nativeCurrency:{name:'Test Ether',symbol:'ETH',decimals:18},rpcUrls:[TESTNET.rpc],blockExplorerUrls:[TESTNET.explorer]}]});}status('Robinhood Chain Testnet selected.');await refresh();});
 $('testRefresh').onclick=()=>run(refresh);$('testDeploy').onclick=()=>run(deploy);$('testLink').onclick=()=>run(link);
 $('testMint').onclick=()=>run(async()=>{const {provider,signer:s}=await signer(),token=new Contract(config.token,artifacts.GetawayTestToken.abi,s),next=await token.nextClaim(await s.getAddress());if(next>BigInt(Math.floor(Date.now()/1000)))throw Error('Your next free token claim opens '+new Date(Number(next)*1000).toLocaleString()+'.');status('Confirm your free tGETAWAY claim in the wallet.');await assertWallet(s);await receipt(provider,(await token.faucet()).hash);status('25,000 tGETAWAY added to your test wallet.');await refresh();});
 $('testImport').onsubmit=e=>{e.preventDefault();const registry=$('registry').value.trim();void run(async()=>{config=await api('setup',{registry});status('Test shop verified and saved to this account.');await refresh();});};
 $('testShare').onclick=()=>run(async()=>{await navigator.clipboard.writeText(location.origin+'/testnet/?registry='+config.registry);status('Test shop link copied. Friends still need access to this Site.');});
 $('reviewCancel').onclick=()=>$('testReview').close();$('reviewConfirm').onclick=()=>{$('testReview').close();void run(burn);};
 $('claimItem').innerHTML=TESTNET_ITEMS.map(i=>'<option value="'+i.itemId+'">'+i.name+'</option>').join('');$('testRecover').onsubmit=e=>{e.preventDefault();const id=Number($('claimItem').value),hash=$('claimHash').value.trim();void run(()=>claim(id,hash));};
 session.subscribe(s=>{const key=[s.account,s.chainId].join(':');if(key!==identity){identity=key;mask=0n;balance=0n;if(config&&!busy)void refresh().catch(e=>status(e.message,true));}});
void load().then(()=>status('Start with your wallet, or import a friend’s deployed test shop.')).catch(e=>status(e.message,true));
